package br.com.mathinclui.auth.token;
import br.com.mathinclui.aluno.repository.AlunoRepository; import br.com.mathinclui.auth.api.AuthProblemException; import br.com.mathinclui.auth.security.*; import br.com.mathinclui.professor.repository.ProfessorRepository; import org.springframework.stereotype.Service;
@Service public class AuthPrincipalResolver { private final ProfessorRepository professorRepository; private final AlunoRepository alunoRepository; public AuthPrincipalResolver(ProfessorRepository professorRepository,AlunoRepository alunoRepository){this.professorRepository=professorRepository;this.alunoRepository=alunoRepository;} public AuthPrincipal resolve(SubjectType type,Long id){ if(type==SubjectType.PROFESSOR){var professor=professorRepository.findById(id).filter(p->p.isAtivo()).orElseThrow(AuthProblemException::invalidCredentials); return new AuthPrincipal(professor.getId(),professor.getNome(),professor.getEmail(),SubjectType.PROFESSOR);} var aluno=alunoRepository.findById(id).filter(a->a.isAtivo()).orElseThrow(AuthProblemException::invalidCredentials); return new AuthPrincipal(aluno.getId(),aluno.getNome(),aluno.getUsername(),SubjectType.ALUNO); } }
